          defaultLocale: "en-US",
          defaultCurrency: "USD",
          supportedLocales: [{ id: "en-US", preferredCurrency: "USD" }],
          supportedCurrencies: ["USD"],
        },
      ],
    },
    url: {
      prefix: "/",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override required.
    // Path detection doesn't find valid site/locale IDs in page path segments
    // and falls through. Both site and locale resolve from cookie or header.
  },
});
```

This configuration produces the cleanest possible URLs with no site or locale identifiers at all. On a first visit with no cookies, the `defaultSiteId` and `defaultLocale` values from `config.server.ts` determine which site and locale are used.

No detection config override is required. Because there is only one site and one locale configured, the defaults are always used on the first visit and persisted via cookies for subsequent requests.

Best for: Single-site, single-locale storefronts that don't need site or locale identifiers in the URL.

