String ValidateAndStringifyValue(ScriptState\* script\_state,

ExceptionState& exception\_state,

ScriptValue input,

const String& value\_name) {

if (!input.V8Value()->IsObject()) {

exception\_state.ThrowTypeError("invalid " + value\_name +

": value is not an object");

return String();

}

v8::Local<v8::String> value;

TryRethrowScope rethrow\_scope(script\_state->GetIsolate(), exception\_state);

if (!v8::JSON::Stringify(script\_state->GetContext(), input.V8Value())

.ToLocal(&value)) {

CHECK(rethrow\_scope.HasCaught());

return String();

}

String result = ToBlinkString<String>(script\_state->GetIsolate(), value,

kDoNotExternalize);

if (result == "undefined") {

exception\_state.ThrowTypeError("invalid " + value\_name +

": toJSON() returns undefined");

return String();

}

return result;

}

ScriptObject JSONStringToScriptObject(ScriptState\* script\_state,

const String& json\_string) {

v8::Local<v8::String> v8\_json\_string =

V8String(script\_state->GetIsolate(), json\_string);

v8::Local<v8::Value> parsed\_value;

if (!v8::JSON::Parse(script\_state->GetContext(), v8\_json\_string)

.ToLocal(&parsed\_value)) {

return ScriptObject();

}

if (!parsed\_value\->IsObject()) {

return ScriptObject();

}

v8::Local<v8::Object> v8\_object = v8::Local<v8::Object>::Cast(parsed\_value);

return ScriptObject(script\_state->GetIsolate(), v8\_object);

}

String ComputeScriptToolResult(const Document& document) {

StringBuilder builder;

builder.Append("\[");

bool first = true;

for (HTMLScriptElement& script\_element :

Traversal<HTMLScriptElement>::DescendantsOf(document)) {

if (static\_cast<ScriptElementBase&>(script\_element).TypeAttributeValue() !=

"application/ld+json") {

continue;

}

const String& json\_raw = script\_element.textContent();

if (json\_raw.empty()) {

continue;

}

JSONParseError error;

std::unique\_ptr<JSONValue> parsed\_json =

ParseJSONWithCommentsDeprecated(json\_raw, &error);

if (!parsed\_json) {

LOG(ERROR) << "JSON parsing failed : " << error.message;

continue;

}

if (!first) {

builder.Append(",");

}

builder.Append(parsed\_json\->ToJSONString());

first = false;

}

builder.Append("\]");

return builder.ToString();

}

String GetToolErrorMessage(const ScriptToolError& error) {

if (!error.message.empty()) {

return error.message;

}

String conversion;

switch (error.code) {

case ScriptToolErrorCode::kInvalidToolName:

conversion = "Tool was not executed due to invalid name";

break;

case ScriptToolErrorCode::kInvalidInputArguments:

conversion = "Tool was not executed due to invalid input arguments";

break;

case ScriptToolErrorCode::kMissingRequiredSubmitButton:

conversion =

"Tool was not executed due to missing required submit button";

break;

case ScriptToolErrorCode::kToolInvocationFailed:

conversion =

"Tool was executed but the invocation failed.

"script function threw an error";

break;

case ScriptToolErrorCode::kToolCancelled:

conversion = "Tool was cancelled";

break;

default:

conversion = "Unknown failure";

}

return conversion;

}

}

class ModelContext::ToolUnregisterAbortAlgorithm final

: public AbortSignal::Algorithm {

public:

ToolUnregisterAbortAlgorithm(ModelContext\* model\_context,

const String& tool\_name,

ScriptPromiseResolverBase\* resolver,

AbortSignal\* signal)

: model\_context\_(model\_context),

tool\_name\_(tool\_name),

resolver\_(resolver),

signal\_(signal) {}

void Run() override {

model\_context\_->UnregisterTool(tool\_name\_);

resolver\_->Reject(signal\_->reason(resolver\_->GetScriptState()));

}

void Trace(Visitor\* visitor) const override {

visitor->Trace(model\_context\_);

visitor->Trace(resolver\_);

visitor->Trace(signal\_);

AbortSignal::Algorithm::Trace(visitor);

}

private:

Member<ModelContext> model\_context\_;

String tool\_name\_;

Member<ScriptPromiseResolverBase> resolver\_;

Member<AbortSignal> signal\_;

};

class ModelContext::ToolFunctionFinishedCallback

: public ThenCallable<IDLAny, ToolFunctionFinishedCallback> {

public:

explicit ToolFunctionFinishedCallback(

ModelContext\* model\_context,

const base::UnguessableToken& invocation\_id,

bool success)

: model\_context\_(model\_context),

invocation\_id\_(invocation\_id),

success\_(success) {}

~ToolFunctionFinishedCallback() override = default;

void React(ScriptState\* script\_state, ScriptValue value) {

if (success\_) {

std::optional<String> result;

if (value.IsObject()) {

v8::TryCatch try\_catch(script\_state->GetIsolate());

v8::Local<v8::String> json\_string;

if (v8::JSON::Stringify(script\_state->GetContext(), value.V8Value())

.ToLocal(&json\_string)) {

result = ToBlinkString<String>(script\_state->GetIsolate(),

json\_string, kDoNotExternalize);

} else {

CHECK(try\_catch.HasCaught());

HandleFailure(script\_state, ScriptValue(script\_state->GetIsolate(),

try\_catch.Exception()));

return;

}

}

if (!result) {

String temp;

if (value.ToString(temp)) {

result.emplace(std::move(temp));

}

}

if (!result || result\->empty()) {

result = "Operation succeeded";

}

model\_context\_->OnToolExecuted(invocation\_id\_, \*result);

} else {

HandleFailure(script\_state, value);

}

}

void Trace(Visitor\* visitor) const override {

ThenCallable<IDLAny, ToolFunctionFinishedCallback>::Trace(visitor);

visitor->Trace(model\_context\_);

}

private:

void HandleFailure(ScriptState\* script\_state, ScriptValue value) {

v8::Isolate\* isolate = script\_state->GetIsolate();

v8::Local<v8::Message> message =

v8::Exception::CreateMessage(isolate, value.V8Value());

String message\_text = ToCoreStringWithNullCheck(isolate, message\->Get());

if (message\_text.empty()) {

message\_text = "Unknown error";

}

SourceLocation\* location = CaptureSourceLocation(

isolate, message, model\_context\_->GetExecutionContext());

model\_context\_->GetExecutionContext()->AddConsoleMessage(

MakeGarbageCollected<ConsoleMessage>(

mojom::blink::ConsoleMessageSource::kJavaScript,

mojom::blink::ConsoleMessageLevel::kError,

"WebMCP tool execution failed: " + message\_text, location));

model\_context\_->OnToolExecuted(

invocation\_id\_, base::unexpected(std::make\_pair(value, script\_state)));

}

Member<ModelContext> model\_context\_;

const base::UnguessableToken invocation\_id\_;

const bool success\_;

};

