ScriptPromise<IDLUndefined> ModelContext::registerTool(

ScriptState\* script\_state,

ModelContextTool\* tool,

ModelContextRegisterToolOptions\* options) {

if (!document\_->IsActive()) {

return ScriptPromise<IDLUndefined>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,

kInactiveDocumentError));

}

if (!IsModelContextAllowed()) {

return ScriptPromise<IDLUndefined>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kSecurityError,

kDocumentDomainEnabledError));

}

if (!ExecutionContext::From(script\_state)

\->IsFeatureEnabled(

network::mojom::PermissionsPolicyFeature::kTools)) {

return ScriptPromise<IDLUndefined>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kNotAllowedError,

kPermissionPolicyNotEnabledError));

}

if (tool\_map\_.find(tool->name()) != tool\_map\_.end()) {

return ScriptPromise<IDLUndefined>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,

"Duplicate tool name"));

}

if (!IsValidScriptToolName(tool->name().Utf8())) {

return ScriptPromise<IDLUndefined>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,

"Invalid tool name"));

}

if (!tool->description() || tool->description().empty()) {

return ScriptPromise<IDLUndefined>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,

"Description is required"));

}

String input\_schema;

if (tool->hasInputSchema()) {

input\_schema = ValidateAndStringifyValue(

script\_state, PassThroughException(script\_state->GetIsolate()),

tool->inputSchema(), "input schema");

if (!input\_schema) {

return EmptyPromise();

}

}

auto\* resolver =

MakeGarbageCollected<ScriptPromiseResolver<IDLUndefined>>(script\_state);

ScriptPromise promise = resolver->Promise();

if (options && options->hasSignal() && options->signal()->aborted()) {

resolver->Reject(options->signal()->reason(script\_state));

return promise;

}

Vector<scoped\_refptr<const SecurityOrigin>> exposed\_origins;

if (options && options->hasExposedTo()) {

for (const String& origin\_str : options->exposedTo()) {

scoped\_refptr<const SecurityOrigin> origin =

SecurityOrigin::CreateFromString(origin\_str);

if (!origin\->IsPotentiallyTrustworthy()) {

resolver->RejectWithDOMException(

DOMExceptionCode::kSecurityError,

"Only secure origins are allowed in the exposedTo list.");

return promise;

}

exposed\_origins.push\_back(origin);

}

}

AbortSignal::AlgorithmHandle\* abort\_handle = nullptr;

if (options && options->hasSignal()) {

AbortSignal\* signal = options->signal();

CHECK(!signal->aborted());

abort\_handle =

signal->AddAlgorithm(MakeGarbageCollected<ToolUnregisterAbortAlgorithm>(

this, tool->name(), resolver, signal));

}

auto script\_tool = mojom::blink::ScriptTool::New();

script\_tool\->name = tool->name();

script\_tool\->title = tool->hasTitle() ? tool->title() : String();

script\_tool\->description = tool->description();

script\_tool\->input\_schema = input\_schema;

script\_tool\->tool\_owner\_frame\_token = document\_->GetFrame()->GetFrameToken();

script\_tool\->origin = document\_->GetExecutionContext()->GetSecurityOrigin();

script\_tool\->exposed\_origins = std::move(exposed\_origins);

if (tool->hasAnnotations()) {

script\_tool\->annotations = mojom::blink::ScriptToolAnnotations::New();

CHECK(tool->annotations()->hasReadOnlyHint());

script\_tool\->annotations->read\_only = tool->annotations()->readOnlyHint();

CHECK(tool->annotations()->hasUntrustedContentHint());

script\_tool\->annotations->untrusted\_content =

tool->annotations()->untrustedContentHint();

CHECK(tool->annotations()->hasConsequentialHint());

script\_tool\->annotations->consequential =

tool->annotations()->consequentialHint();

}

auto\* tool\_data = MakeGarbageCollected<ToolData>(

base::PassKey<ModelContext>(), std::move(script\_tool),

tool->execute(),

CaptureSourceLocation(ExecutionContext::From(script\_state)),

abort\_handle);

tool\_map\_.insert(tool->name(), tool\_data);

model\_context\_host\_remote\_->RegisterScriptTool(

tool\_data->ScriptTool().Clone(),

blink::BindOnce(

\[\] {

resolver->Resolve();

},

WrapPersistent(resolver)));

probe::WebMCPToolAdded(document\_, \*tool\_data);

MaybeRecordToolCount();

return promise;

}

