bool ModelContext::ExecuteTool(const base::UnguessableToken& invocation\_id,

const String& name,

const String& input\_arguments,

ScriptToolExecutedCallback tool\_executed\_cb) {

CHECK(document\_->GetFrame());

ScriptState\* script\_state = ToScriptStateForMainWorld(document\_->GetFrame());

CHECK(script\_state->ContextIsValid());

AbortController\* abort\_controller = nullptr;

{

ScriptState::Scope scope(script\_state);

abort\_controller = AbortController::Create(script\_state);

}

CHECK(abort\_controller);

probe::WebMCPToolExecuted(document\_, name, input\_arguments, invocation\_id);

auto it = tool\_map\_.find(name);

if (it == tool\_map\_.end()) {

OnToolFailed(std::move(tool\_executed\_cb), invocation\_id,

ScriptToolError(ScriptToolErrorCode::kInvalidToolName,

String("Tool not found: " + name)));

return false;

}

bool success = true;

if (V8ToolExecuteCallback\* v8\_tool\_function =

it\->value->GetV8ToolExecuteCallback()) {

success =

ExecuteV8Tool(v8\_tool\_function, invocation\_id, name, input\_arguments,

abort\_controller, std::move(tool\_executed\_cb));

} else {

ExecuteDeclarativeTool(it\->value->DeclarativeTool(), invocation\_id,

input\_arguments, abort\_controller,

std::move(tool\_executed\_cb));

}

if (LocalDOMWindow\* window = document\_->domWindow()) {

window->DispatchEvent(

\*WebMCPEvent::Create(event\_type\_names::kToolactivated, name));

}

return success;

}

bool ModelContext::CancelTool(const base::UnguessableToken& invocation\_id) {

CHECK(document\_->IsActive());

auto it = pending\_executions\_.find(invocation\_id);

if (it == pending\_executions\_.end()) {

return false;

}

String tool\_name = it\->value.tool\_name;

auto tool\_it = tool\_map\_.find(tool\_name);

if (tool\_it != tool\_map\_.end() && tool\_it\->value->DeclarativeTool()) {

tool\_it\->value->DeclarativeTool()->CancelTool();

CHECK(!pending\_executions\_.Contains(invocation\_id));

} else {

auto pending\_execution = pending\_executions\_.Take(invocation\_id);

CHECK(pending\_execution.abort\_controller);

CHECK(pending\_execution.callback);

ScriptState\* script\_state =

ToScriptStateForMainWorld(document\_->GetFrame());

if (script\_state && script\_state->ContextIsValid()) {

ScriptState::Scope scope(script\_state);

pending\_execution.abort\_controller->abort(script\_state);

}

OnToolFailed(std::move(pending\_execution.callback), invocation\_id,

ScriptToolError(ScriptToolErrorCode::kToolCancelled));

}

if (LocalDOMWindow\* window = document\_->domWindow()) {

window->DispatchEvent(

\*WebMCPEvent::Create(event\_type\_names::kToolcancel, tool\_name));

}

return true;

}

void ModelContext::GetCrossDocumentScriptToolResult(

const base::UnguessableToken& invocation\_id,

CrossDocumentScriptToolResultCallback result\_callback) {

if (document\_->HasFinishedParsing()) {

String result = ComputeScriptToolResult(\*document\_);

probe::WebMCPToolResponded(document\_, result, invocation\_id);

std::move(result\_callback).Run(result);

return;

}

cross\_document\_result\_callbacks\_.push\_back(blink::BindOnce(

\[\](CrossDocumentScriptToolResultCallback original\_callback,

const base::UnguessableToken& invocation\_id, Document\* document,

String result) {

probe::WebMCPToolResponded(document, result, invocation\_id);

std::move(original\_callback).Run(result);

},

std::move(result\_callback), invocation\_id,

WrapPersistent(document\_.Get())));

}

void ModelContext::DidFinishParsing() {

if (cross\_document\_result\_callbacks\_.empty()) {

return;

}

auto result = ComputeScriptToolResult(\*document\_);

for (auto& callback : cross\_document\_result\_callbacks\_) {

std::move(callback).Run(result);

}

cross\_document\_result\_callbacks\_.clear();

}

void ModelContext::ExecuteDeclarativeTool(

DeclarativeWebMCPTool\* tool,

const base::UnguessableToken& invocation\_id,

const String& input\_arguments,

AbortController\* abort\_controller,

ScriptToolExecutedCallback tool\_executed\_cb) {

CHECK(abort\_controller);

std::optional<scheduler::TaskAttributionTracker::TaskScope> task\_scope;

if (auto\* tracker = document\_->GetAgent().isolate()

? scheduler::TaskAttributionTracker::From(

document\_->GetAgent().isolate())

: nullptr) {

task\_scope = tracker->SetTaskStateVariable(

MakeGarbageCollected<ScriptToolContext>(invocation\_id));

}

pending\_executions\_.insert(invocation\_id,

PendingExecution{

.tool\_name = tool->ToolName(),

.callback = std::move(tool\_executed\_cb),

.abort\_controller = abort\_controller,

});

tool->ExecuteTool(

invocation\_id, input\_arguments,

blink::BindOnce(

\[\](Document\* document, base::UnguessableToken invocation\_id,

base::expected<String, ScriptToolError> result) {

CHECK(document);

ModelContext\* model\_context =

ModelContextSupplement::modelContext(\*document);

CHECK(model\_context);

if (result.has\_value()) {

if (!result\->IsNull()) {

probe::WebMCPToolResponded(document, \*result, invocation\_id);

}

} else {

probe::WebMCPToolFailed(document, result.error(), invocation\_id,

std::nullopt);

}

auto it = model\_context->pending\_executions\_.find(invocation\_id);

if (it != model\_context->pending\_executions\_.end()) {

std::move(it\->value.callback).Run(result);

model\_context->pending\_executions\_.erase(it);

}

},

WrapWeakPersistent(document\_.Get()), invocation\_id));

}

bool ModelContext::ExecuteV8Tool(V8ToolExecuteCallback\* tool\_function,

const base::UnguessableToken& invocation\_id,

const String& name,

const String& input\_arguments,

AbortController\* abort\_controller,

ScriptToolExecutedCallback tool\_executed\_cb) {

UseCounter::Count(document\_, WebFeature::kModelContextExecuteImperativeTool);

CHECK(abort\_controller);

ScriptState\* script\_state = tool\_function->CallbackRelevantScriptState();

ScriptState::Scope scope(script\_state);

v8::TryCatch try\_catch(script\_state->GetIsolate());

auto script\_object = JSONStringToScriptObject(script\_state, input\_arguments);

ScriptValue script\_value = script\_object;

if (try\_catch.HasCaught() || script\_value.IsEmpty()) {

OnToolFailed(std::move(tool\_executed\_cb), invocation\_id,

ScriptToolError(ScriptToolErrorCode::kInvalidInputArguments,

"Failed to parse input arguments"));

return false;

}

std::optional<scheduler::TaskAttributionTracker::TaskScope> task\_scope;

if (auto\* tracker =

scheduler::TaskAttributionTracker::From(script\_state->GetIsolate())) {

task\_scope = tracker->SetTaskStateVariable(

MakeGarbageCollected<ScriptToolContext>(invocation\_id));

}

ToolExecuteCallbackOptions\* execute\_options =

ToolExecuteCallbackOptions::Create();

execute\_options->setSignal(abort\_controller->signal());

v8::Maybe<ScriptPromise<IDLAny>> maybe\_result =

tool\_function->Invoke(nullptr, std::move(script\_object), execute\_options);

ScriptPromise<IDLAny> result;

if (maybe\_result.IsNothing()) {

result = ScriptPromise<IDLAny>::RejectWithDOMException(

script\_state, MakeGarbageCollected<DOMException>(

DOMExceptionCode::kAbortError, "Failure"));

} else {

result = maybe\_result.FromJust();

}

pending\_executions\_.insert(invocation\_id,

PendingExecution{

.tool\_name = name,

.callback = std::move(tool\_executed\_cb),

.abort\_controller = abort\_controller,

});

result.Then(script\_state,

MakeGarbageCollected<ToolFunctionFinishedCallback>(

this, invocation\_id, true),

MakeGarbageCollected<ToolFunctionFinishedCallback>(

this, invocation\_id, false));

return true;

}

void ModelContext::RegisterDeclarativeTool(

DeclarativeWebMCPTool\* declarative\_tool) {

if (!document\_->GetExecutionContext()->IsFeatureEnabled(

network::mojom::PermissionsPolicyFeature::kTools)) {

return;

}

if (!IsModelContextAllowed()) {

return;

}

if (tool\_map\_.find(declarative\_tool->ToolName()) != tool\_map\_.end()) {

return;

}

if (!IsValidScriptToolName(declarative\_tool->ToolName().Utf8())) {

return;

}

UseCounter::Count(document\_,

WebFeature::kModelContextRegisterDeclarativeTool);

auto script\_tool = mojom::blink::ScriptTool::New();

script\_tool\->name = declarative\_tool->ToolName();

script\_tool\->description = declarative\_tool->ToolDescription();

script\_tool\->title = declarative\_tool->ToolTitle();

script\_tool\->input\_schema = declarative\_tool->ComputeInputSchema();

script\_tool\->tool\_owner\_frame\_token = document\_->GetFrame()->GetFrameToken();

script\_tool\->origin = document\_->GetExecutionContext()->GetSecurityOrigin();

auto\* tool\_data = MakeGarbageCollected<ToolData>(

base::PassKey<ModelContext>(), std::move(script\_tool), declarative\_tool);

tool\_map\_.insert(declarative\_tool->ToolName(), tool\_data);

model\_context\_host\_remote\_->RegisterScriptTool(

tool\_data->ScriptTool().Clone(), base::DoNothing());

probe::WebMCPToolAdded(document\_, \*tool\_data);

MaybeRecordToolCount();

}

