ScriptPromise<IDLSequence<RegisteredTool>> ModelContext::getTools(

ScriptState\* script\_state,

const ModelContextGetToolOptions\* options) {

if (!document\_->IsActive()) {

return ScriptPromise<IDLSequence<RegisteredTool>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,

kInactiveDocumentError));

}

if (!IsModelContextAllowed()) {

return ScriptPromise<IDLSequence<RegisteredTool>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kSecurityError,

kDocumentDomainEnabledError));

}

if (!ExecutionContext::From(script\_state)

\->IsFeatureEnabled(

network::mojom::PermissionsPolicyFeature::kTools)) {

return ScriptPromise<IDLSequence<RegisteredTool>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kNotAllowedError,

kPermissionPolicyNotEnabledError));

}

Vector<scoped\_refptr<const SecurityOrigin>> from\_origins;

if (options && options->hasFromOrigins()) {

for (const String& origin\_str : options->fromOrigins()) {

scoped\_refptr<const SecurityOrigin> origin =

SecurityOrigin::CreateFromString(origin\_str);

if (!origin\->IsPotentiallyTrustworthy()) {

return ScriptPromise<IDLSequence<RegisteredTool>>::

RejectWithDOMException(script\_state,

MakeGarbageCollected<DOMException>(

DOMExceptionCode::kSecurityError,

"Only secure origins are allowed in the "

"fromOrigins list."));

}

from\_origins.push\_back(origin);

}

}

auto\* resolver =

MakeGarbageCollected<ScriptPromiseResolver<IDLSequence<RegisteredTool>>>(

script\_state);

ScriptPromise promise = resolver->Promise();

model\_context\_host\_remote\_->GetScriptTools(

std::move(from\_origins),

blink::BindOnce(&ModelContext::OnGetScriptToolsCompleted,

WrapWeakPersistent(this), WrapPersistent(resolver)));

return promise;

}

void ModelContext::OnGetScriptToolsCompleted(

ScriptPromiseResolver<IDLSequence<RegisteredTool>>\* resolver,

Vector<mojom::blink::ScriptToolPtr> tools) {

HeapVector<Member<RegisteredTool>> registered\_tools;

registered\_tools.ReserveInitialCapacity(tools.size());

for (const auto& t : tools) {

auto\* result = RegisteredTool::Create();

result->setName(t->name);

result->setTitle(t->title);

result->setDescription(t->description);

if (!t->input\_schema.IsNull()) {

ScriptState\* script\_state = resolver->GetScriptState();

ScriptState::Scope scope(script\_state);

v8::TryCatch try\_catch(script\_state->GetIsolate());

auto script\_object =

JSONStringToScriptObject(script\_state, t->input\_schema);

ScriptValue script\_value = script\_object;

if (try\_catch.HasCaught() || script\_value.IsEmpty()) {

continue;

}

result->setInputSchema(script\_object);

}

if (t->annotations) {

auto\* annotations = ToolAnnotations::Create();

annotations->setReadOnlyHint(t->annotations->read\_only);

annotations->setUntrustedContentHint(t->annotations->untrusted\_content);

annotations->setConsequentialHint(t->annotations->consequential);

result->setAnnotations(annotations);

}

Frame\* frame = Frame::ResolveFrame(t->tool\_owner\_frame\_token);

if (!frame) {

continue;

}

result->setWindow(frame->DomWindow());

result->setOrigin(t->origin->ToString());

registered\_tools.push\_back(result);

}

resolver->Resolve(registered\_tools);

}

ScriptPromise<IDLNullable<IDLString>> ModelContext::executeTool(

ScriptState\* script\_state,

RegisteredTool\* tool,

ScriptValue input\_object,

const ExecuteToolOptions\* options) {

if (!document\_->IsActive()) {

return ScriptPromise<IDLNullable<IDLString>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,

kInactiveDocumentError));

}

if (!IsModelContextAllowed()) {

return ScriptPromise<IDLNullable<IDLString>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kSecurityError,

kDocumentDomainEnabledError));

}

if (!ExecutionContext::From(script\_state)

\->IsFeatureEnabled(

network::mojom::PermissionsPolicyFeature::kTools)) {

return ScriptPromise<IDLNullable<IDLString>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kNotAllowedError,

kPermissionPolicyNotEnabledError));

}

KURL expected\_url(NullUrl(), tool->origin());

if (!expected\_url.IsValid()) {

return ScriptPromise<IDLNullable<IDLString>>::RejectWithDOMException(

script\_state,

MakeGarbageCollected<DOMException>(DOMExceptionCode::kNotSupportedError,

"The provided origin is invalid."));

}

scoped\_refptr<SecurityOrigin> expected\_target\_origin =

SecurityOrigin::Create(expected\_url);

if (expected\_target\_origin\->IsOpaque()) {

return ScriptPromise<IDLNullable<IDLString>>::RejectWithDOMException(

script\_state, MakeGarbageCollected<DOMException>(

DOMExceptionCode::kNotSupportedError,

"Cannot execute tools that live in a document with "

"an opaque origin."));

}

String input\_arguments = ValidateAndStringifyValue(

script\_state, PassThroughException(script\_state->GetIsolate()),

input\_object, "input object");

if (!input\_arguments) {

return EmptyPromise();

}

auto\* resolver =

MakeGarbageCollected<ScriptPromiseResolver<IDLNullable<IDLString>>>(

script\_state);

ScriptPromise promise = resolver->Promise();

DOMWindow\* window = tool->window();

CHECK(window);

Frame\* target\_frame = window->GetFrame();

if (!target\_frame) {

resolver->RejectWithDOMException(DOMExceptionCode::kInvalidStateError,

"Target frame is detached.");

return promise;

}

blink::FrameToken frame\_token = target\_frame->GetFrameToken();

LocalFrame\* local\_frame = document\_->GetFrame();

CHECK(local\_frame);

base::UnguessableToken invocation\_id = base::UnguessableToken::Create();

std::unique\_ptr<ScopedAbortState> scoped\_abort\_state;

if (options && options->hasSignal()) {

AbortSignal\* signal = options->signal();

if (signal->aborted()) {

resolver->Reject(signal->reason(resolver->GetScriptState()));

return promise;

}

auto\* handle = signal->AddAlgorithm(blink::BindOnce(

\[\](ModelContext\* self,

ScriptPromiseResolver<IDLNullable<IDLString>>\* resolver,

ScriptState\* script\_state, AbortSignal\* signal,

const base::UnguessableToken& invocation\_id) {

if (resolver->GetScriptState() &&

resolver->GetScriptState()->ContextIsValid()) {

resolver->Reject(signal->reason(script\_state));

}

if (self && self->model\_context\_host\_remote\_.is\_bound()) {

self->model\_context\_host\_remote\_->CancelRemoteScriptTool(

invocation\_id);

}

},

WrapWeakPersistent(this), WrapPersistent(resolver),

WrapPersistent(script\_state), WrapPersistent(signal), invocation\_id));

scoped\_abort\_state = std::make\_unique<ScopedAbortState>(signal, handle);

}

model\_context\_host\_remote\_->ExecuteRemoteScriptTool(

invocation\_id, frame\_token, expected\_target\_origin, tool->name(),

input\_arguments,

blink::BindOnce(&ModelContext::OnExecuteScriptToolCompleted,

WrapWeakPersistent(this), WrapPersistent(resolver),

std::move(scoped\_abort\_state)));

return promise;

}

void ModelContext::OnExecuteScriptToolCompleted(

ScriptPromiseResolver<IDLNullable<IDLString>>\* resolver,

std::unique\_ptr<ScopedAbortState> abort\_state,

const String& result,

bool success) {

CHECK(resolver->GetScriptState() &&

resolver->GetScriptState()->ContextIsValid());

if (success) {

resolver->Resolve(result);

} else {

resolver->RejectWithDOMException(DOMExceptionCode::kUnknownError, result);

}

}

