## [SFRA] / [Server-side JS] / Source: modules/server/response.js

```
'use strict';

var assign = require('./assign');
var httpHeadersConfig = require('*/cartridge/config/httpHeadersConf');

/**
 * @constructor
 * @classdesc Creates writtable response object
 *
 * @param {Object} response - Global response object
 */
function Response(response) {
    this.view = null;
    this.viewData = {};
    this.redirectUrl = null;
    this.redirectStatus = null;
    this.messageLog = [];
    this.base = response;
    this.cachePeriod = null;
    this.cachePeriodUnit = null;
    this.personalized = false;
    this.renderings = [];
    httpHeadersConfig.forEach(function (httpHeader) {
        this.setHttpHeader(httpHeader.id, httpHeader.value);
    }, this);
}

/**
 * Stores a list of rendering steps.
 * @param {Array} renderings - The array of rendering steps
 * @param {Object} object - An object containing what type to render
 * @returns {void}
 */
function appendRenderings(renderings, object) {
    var hasRendering = false;

    if (renderings.length) {
        for (var i = renderings.length - 1; i >= 0; i--) {
            if (renderings[i].type === 'render') {
                renderings[i] = object; // eslint-disable-line no-param-reassign
                hasRendering = true;
                break;
            }
        }
    }

    if (!hasRendering) {
        renderings.push(object);
    }
}

Response.prototype = {
    /**
     * Stores template name and data for rendering at the later time
     * @param {string} name - Path to a template
     * @param {Object} data - Data to be passed to the template
     * @returns {void}
     */
    render: function render(name, data) {
        this.view = name;
        this.viewData = assign(this.viewData, data);

        appendRenderings(this.renderings, { type: 'render', subType: 'isml', view: name });
    },
    /**
     * Stores data to be rendered as json
     * @param {Object} data - Data to be rendered as json
     * @returns {void}
     */
    json: function json(data) {
        this.isJson = true;
        this.viewData = assign(this.viewData, data);

        appendRenderings(this.renderings, { type: 'render', subType: 'json' });
    },
    /**
     * Stores data to be rendered as XML
     * @param {string} xmlString - The XML to print.
     * @returns {void}
     */
    xml: function xml(xmlString) {
        this.isXml = true;
        this.viewData = assign(this.viewData, { xml: xmlString });

        appendRenderings(this.renderings, { type: 'render', subType: 'xml' });
    },
    /**
     * Stores data to be rendered as a page designer page
     * @param {string} page - ID of the page to be rendered
     * @param {Object} data - Data to be passed to the template
     * @param {dw.util.HashMap} aspectAttributes - (optional) aspect attributes to be passed to the PageMgr
     * @returns {void}
     */
    page: function (page, data, aspectAttributes) {
        this.viewData = assign(this.viewData, data);
        appendRenderings(this.renderings, { type: 'render', subType: 'page', page: page, aspectAttributes: aspectAttributes });
    },
    /**
     * Redirects to a given url right away
     * @param {string} url - Url to be redirected to
     * @returns {void}
     */
    redirect: function redirect(url) {
        this.redirectUrl = url;
    },
    /**
     * Sets an optional redirect status, standard cases being 301 or 302.
     * @param {string} redirectStatus - HTTP redirect status code
     * @returns {void}
     */
    setRedirectStatus: function setRedirectStatus(redirectStatus) {
        this.redirectStatus = redirectStatus;
    },
    /**
     * Get data that was setup for a template
     * @returns {Object} Data for the template
     */
    getViewData: function () {
        return this.viewData;
    },
    /**
     * Updates data for the template
     * @param {Object} data - Data for template
     * @returns {void}
     */
    setViewData: function (data) {
        this.viewData = assign(this.viewData, data);
    },
    /**
     * Logs information for output on the error page
     * @param {string[]} arguments - List of items to be logged
     * @returns {void}
     */
    log: function log() {
        var args = Array.prototype.slice.call(arguments);

        var output = args.map(function (item) {
            if (typeof item === 'object' || Array.isArray(item)) {
                return JSON.stringify(item);
            }
            return item;
        });

        this.messageLog.push(output.join(' '));
    },
    /**
     * Set content type for the output
     * @param {string} type - Type of the output
     * @returns {void}
     */
    setContentType: function setContentType(type) {
        this.base.setContentType(type);
    },

    /**
     * Set status code of the response
     * @param {int} code - Valid HTTP return code
     * @returns {void}
     */
    setStatusCode: function setStatusCode(code) {
        this.base.setStatus(code);
    },

    /**
     * creates a print step to the renderings
     * @param {string} message - Message to be printed
     * @returns {void}
     */
    print: function print(message) {
        this.renderings.push({ type: 'print', message: message });
    },

    /**
     * Sets current page cache expiration period value in hours
     * @param  {int} period Number of hours from current time
     * @return {void}
     */
    cacheExpiration: function cacheExpiration(period) {
        this.cachePeriod = period;
    },

    /**
     * Adds a response header with the given name and value
     * @param  {string} name - the name to use for the response header
     * @param  {string} value - the value to use
     * @return {void}
     */
    setHttpHeader: function setHttpHeader(name, value) {
        this.base.setHttpHeader(name, value);
    }

};

module.exports = Response;
```

## Configure Site-Context Cookies

The `siteContext` config in `config.server.ts` controls how site-context cookies are stored. Site-context cookies are site, locale, and currency cookies.

```typescript
// config.server.ts
export default defineConfig({
  app: {
    siteContext: {
      currencyCookieName: "currency",
      cookieOptions: {
        httpOnly: true,
        secure: true,
        sameSite: "lax",
        maxAge: 604800, // 7 days
      },
    },
  },
});
```

- **`currencyCookieName`**—The cookie name used to persist the shopper's selected currency. Defaults to `'currency'`.
- **`cookieOptions`**—Cookie attributes that are applied to all three site-context cookies: site, locale, and currency. Valid options include `httpOnly`, `maxAge`, `secure`, `sameSite`, `path`, `domain`, and so on. These options follow the standard [Cookie] options from React Router. Defaults to `{ path: '/', sameSite: 'lax', secure: true, httpOnly: true }`.

### Creating a Web Service Script

Your web service script must import the `dw.svc`package.

Use `LocalServiceRegistry.createService` to create a `Service` object. Also include business logic to control the parameters used to invoke the web service.

Use `Service.call` to invoke the web service.

When the service is invoked, the service framework checks the circuit breaker and rate limiter. If neither are triggered, then the callback methods in the service instance are executed, and the `dw.svc.Result` object is stored in the `Service`.

Example 1: Simple FTP Service Call

In this example, the operation invoked for the web service is determined by an input variable passed from the pipeline.

```javascript
/**
 *  testFTPClient.ds
 *

 *   @input testType : String
 *   @input numCalls : String
 *   @output svcConfig : dw.svc.Service
 *   @output ftpResult : dw.svc.Result
 *
 */
importPackage(dw.util);
importPackage(dw.svc);
importPackage(dw.net);
importPackage(dw.io);

function execute(args: PipelineDictionary): Number {
  var service: Service;
  var result: Result;
  var counter = args.numCalls;
  var mockCall = false;
  var pipelineError = false;

  var callTestFTP = LocalServiceRegistry.createService("test.ftp", {
    mockCall: function (svc: FTPService, params) {
      return [
        {
          name: "testfile1",
          timestamp: new Date(2011, 02, 21),
        },
        {
          name: "testfile2",
          timestamp: new Date(2012, 02, 21),
        },
        {
          name: "testfile3",
          timestamp: new Date(2013, 02, 21),
        },
      ];
    },
    createRequest: function (svc: FTPService, args) {
      return svc;
    },
    parseResponse: function (svc: FTPService, result: Array) {
      var ret: Array = [];
      for (var i = 0; i < result.length; i++) {
        ret.push(result[i].name);
      }
      ret.sort();
      return ret;
    },
  });

  // Execute the request on the service configuration
  function makeCall(svcConfig: Service, params: Object) {
    if (counter == null) {
      counter = 1;
    }

    while (counter != 0) {
      if (mockCall) {
        result = service.setMock().call(params);
      } else if (pipelineError) {
        result = service.setThrowOnError().call(params);
      } else {
        result = service.call(params);
      }
      counter--;
    }

    // Set pdict out values
    args.svcConfig = service;
    args.ftpResult = result;
  }

  switch (args.testType) {
    case "LIST":
      service = callTestFTP;
      service.setOperation("list");
      break;
    case "CD":
      service = callTestFTP;
      service.setOperation("cd", "/");
      break;
    case "MKDIR":
      service = callTestFTP;
      service.setOperation("mkdir", "test");
      break;
    case "DELETE":
      service = callTestFTP;
      service.setOperation("del", "test");
      break;
  }

  makeCall(service);

  if (result == null || service == null) {
    return PIPELET_ERROR;
  }

  return PIPELET_NEXT;
}
```

Example 2: Modifying the Service Object for an HTTP Service

This example demonstrates how to use the methods on the `Service` object to modify the `Service` object before invoking the service. The ENCODING case in this example adds a header, URL parameters, and changes the encoding before invoking the service.

```javascript
/**
 * testHTTPClient.ds
 *
 *   @input testType : String the type of test to run.
 *	 @input numCalls : String the number of calls to make.
 *   @input returnCode : String the simulated http return code.
 *	 @output svcConfig : dw.svc.Service the service configuration object.
 *   @output httpResult : dw.svc.Result the http result object.
 *
 */
importPackage(dw.system);
importPackage(dw.svc);
importPackage(dw.net);
importPackage(dw.io);

function execute(args: PipelineDictionary): Number {
  var service: Service;
  var result: Result;
  var counter = args.numCalls;
  var mockCall = false;
  var pipelineError = false;
  var returnCode = args.returnCode;
  var requestBody = {
    testString: "foo",
    testNum: 5,
    testBool: true,
  };

  var callTestGet = LocalServiceRegistry.createService("test.http.get", {
    createRequest: function (svc: HTTPService, args) {
      svc.setRequestMethod("GET");
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
    mockCall: function (svc: HTTPService, client: HTTPClient) {
      return {
        statusCode: 200,
        statusMessage: "Success",
        text: "MOCK RESPONSE (" + svc.URL + ")",
      };
    },
    filterLogMessage: function (msg: String) {
      return msg.replace("headers", "OFFWITHTHEHEADERS");
    },
  });

  var callTestPost = LocalServiceRegistry.createService("test.http.post", {
    createRequest: function (svc: HTTPService, args) {
      // Default request method is post
      // No need to setRequestMethod
      if (args) {
        svc.addHeader("Content-Type", "text/json");
        return JSON.stringify(args);
      } else {
        return null;
      }
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
  });

  var callTestPut = LocalServiceRegistry.createService("test.http.put", {
    createRequest: function (svc: HTTPService, args) {
      svc.setRequestMethod("PUT");
      if (args) {
        svc.addHeader("Content-Type", "text/json");
        return JSON.stringify(args);
      } else {
        return null;
      }
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
  });

  var callTestDelete = LocalServiceRegistry.createService("test.http.delete", {
    createRequest: function (svc: HTTPService, args) {
      svc.setRequestMethod("DELETE");
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
  });

  var callTestBasicAuth = LocalServiceRegistry.createService("test.http.basicauth", {
    createRequest: function (svc: HTTPService, args) {
      svc.setRequestMethod("GET");
      svc.setAuthentication("BASIC");
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
  });

  var callTestTimeout = LocalServiceRegistry.createService("test.http.timeout", {
    createRequest: function (svc: HTTPService, args) {
      svc.setRequestMethod("GET");
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
  });

  var callTestStatus = LocalServiceRegistry.createService("test.http.status", {
    createRequest: function (svc: HTTPService, args) {
      svc.setRequestMethod("GET");
    },
    parseResponse: function (svc: HTTPService, client: HTTPClient) {
      return client.text;
    },
  });

  // Execute the request on the service configuration
  function makeCall(svcConfig: Service, params: Object) {
    if (counter == null) {
      counter = 1;
    }

    while (counter != 0) {
      if (mockCall) {
        result = service.setMock().call(params);
      } else if (pipelineError) {
        result = service.setThrowOnError().call(params);
      } else {
        result = service.call(params);
      }
      counter--;
    }

    // Set pdict out values
    args.svcConfig = svcConfig;
    args.httpResult = result;
  }

  switch (args.testType) {
    // make a GET request with additional headers, query param, json payload
    case "GET":
      service = callTestGet;
      service.URL += "/get";
      service.addHeader("testHeader", "testHeaderValue").addParam("filter", true);
      break;

    // make a POST request with additional headers, query param, json payload
    case "POST":
      service = callTestPost;
      service.URL += "/post";
      service.addHeader("testHeader", "testHeaderValue");
      break;

    // make a POST request with additional headers, query param, json payload, using UTF-16 encoding
    case "ENCODING":
      service = callTestPost;
      service.setEncoding("UTF-16");
      break;

    // make a PUT request with additional headers, query param concatenation, json payload
    case "PUT":
      service = callTestPut;
      service.URL += "/put";
      service.addParam("filter", true).addParam("secondParamAmpersand", 1);
      break;

    // make a DELETE request with additional headers, query param, json payload
    case "DELETE":
      service = callTestDelete;
      service.URL += "/delete";
      service.addHeader("testHeader", "testHeaderValue").addParam("filter", true);
      break;

    // make an HTTP post with BASIC auth.
    case "BASICAUTH":
      service = callTestBasicAuth;
      service.URL += "/basic-auth/user/passwd";
      break;

    // make a GET request with timeout
    case "TIMEOUT":
      service = callTestTimeout;
      service.URL += "/delay/6";
      break;

    // make a GET request and write result object to file
    case "OUTFILE":
      service = callTestGet;
      service.setOutFile(File("TEMP/" + Math.random()));
      break;

    // make a GET request in explicit mock mode
    case "MOCKED":
      service = ServiceRegistry.get("test.http.get");
      mockCall = true;
      break;

    // make a GET request and test ratelimit
    case "RATELIMIT":
      service = callTestGet;
      service.URL += "/get";
      break;

    // make a GET request with status code return as specified by returnCode pipeline query param
    case "STATUS":
      service = callTestStatus;
      if (returnCode == null) {
        trace("No return code provided");
      }
      service.URL += "/status/" + returnCode;
      break;

    // make a GET request and throwOnError() to have PIPELINE handle response error.
    case "THROWONERROR":
      service = callTestStatus;
      service.URL += "/status/" + 500;
      counter = 20;
      pipelineError = true;
      break;
  }

  // Make the service call here
  makeCall(service, requestBody);

  if (result == null || service == null) {
    return PIPELET_ERROR;
  }

  return PIPELET_NEXT;
}
```

### Basic Component Example

This code example defines a Hero Banner Page Designer component. `@Component` registers the banner, and `@AttributeDefinition` on `HeroMetadata` declares optional configurable fields, such as `Title`, `Image`, and `CTA link`, a call-to-action link. You can configure the Hero Banner in Page Designer.

```tsx
// src/components/hero/index.tsx
import { Component } from "@/lib/decorators/component";
import { AttributeDefinition } from "@/lib/decorators/attribute-definition";

@Component("hero", {
  name: "Hero Banner",
  group: "odyssey_base",
  description: "Prominent banner section with title, image, and CTA",
})
export class HeroMetadata {
  @AttributeDefinition({
    name: "Title",
    type: "string",
    required: false,
  })
  title?: string;

  @AttributeDefinition({
    name: "Image",
    type: "image",
    required: false,
  })
  imageUrl?: string;

  @AttributeDefinition({
    name: "CTA Link",
    type: "url",
    required: false,
  })
  ctaLink?: string;
}

// Fallback component (shown while loading)
export function fallback({ title }: Partial<HeroProps>) {
  return (
    <div className="h-64 bg-gray-200 animate-pulse">
      {title && <span className="sr-only">{title}</span>}
    </div>
  );
}

// Main component (default export required)
export default function Hero({ title, imageUrl, ctaLink, ctaText }: HeroProps) {
  return (
    <section className="hero">
      <img src={imageUrl} alt={title} />
      <h1>{title}</h1>
      {ctaLink && <a href={ctaLink}>{ctaText}</a>}
    </section>
  );
}
```

### 3\. Event-Based Tool Execution (`'toolcall'`)

Another alternative was to handle tool execution exclusively via window-level events:

document.agent.addEventListener('toolcall', async (e) \=> {
  if (e.name \=== 'add-todo') {
    e.respondWith(handleAddTodo(e.arguments));
  }
});

*   _Disadvantages_: This approach separates a tool's schema declaration from its implementation, making it harder to keep definitions and code in sync. It also leads to large `switch-case` statement blocks in event handlers.
*   _Hybrid Approach_: We may still consider a hybrid model where a `"toolcall"` event is dispatched on the window _before_ falling back to executing the registered imperative `execute` callback, allowing advanced interception.

