### Migration Steps

#### Step 1: Install Required Dependency

Add the `@salesforce/storefront-next-runtime` package to your project:

```bash
npm install @salesforce/storefront-next-runtime
```

Update your `package.json`:

```json
{
  "dependencies": {
    "@salesforce/storefront-next-runtime": "^VERSION",
    "@salesforce/commerce-sdk-react": "^VERSION"
  }
}
```

#### Step 2: Update Component Metadata to Headless

For **each existing component** in your cartridge, update the JSON metadata file to include `arch_type: "headless"`:

**Before** (`cartridge/experience/components/commerce_assets/photoTile.json`):

```json
{
    "name": "Photo Tile",
    "description": "Image display component",
    "group": "commerce_assets",
    "attribute_definition_groups": [...]
}
```

**After**:

```json
{
    "name": "Photo Tile",
    "description": "Image display component",
    "group": "commerce_assets",
    "arch_type": "headless",
    "region_definitions": [],
    "attribute_definition_groups": [...]
}
```

**Required changes for each component**:

- Add `"arch_type": "headless"`.
- Add `"region_definitions": []` for leaf components, or populate with regions for layout components.

#### Step 3: Update Page Metadata with Routes

For **each existing page** in your cartridge, update the JSON metadata to include `arch_type` and `route`:

**Before** (`cartridge/experience/pages/homePage.json`):

```json
{
    "name": "Home Page",
    "description": "Main landing page",
    "region_definitions": [...]
}
```

**After**:

```json
{
    "name": "Home Page",
    "description": "Main landing page",
    "arch_type": "headless",
    "route": "/",
    "region_definitions": [...]
}
```

**Route examples**:

- Homepage: `"route": "/"`
- Static pages: `"route": "/about"`, `"route": "/contact"`
- Product pages: `"route": "/product/:productId"` (`:productId` matches the attribute ID in your aspect type)
- Category pages: `"route": "/category/:categoryId"` (`:categoryId` matches the attribute ID in your aspect type)

#### Step 4: Update Aspect Type Metadata

For **each aspect type** (PDP, PLP, Search), add `arch_type`:

**Before** (`cartridge/experience/aspects/pdp.json`):

```json
{
    "name": "Product detail page",
    "description": "A product detail page",
    "attribute_definitions": [...],
    "supported_object_types": ["product"]
}
```

**After**:

```json
{
    "name": "Product detail page",
    "description": "A product detail page",
    "arch_type": "headless",
    "attribute_definitions": [...],
    "supported_object_types": ["product"]
}
```

#### Step 5: Migrate from Manual Mapping to Registry

Replace the old manual component mapping with the new registry approach.

**Remove** the old mapping pattern from your page-viewer:

```jsx
// OLD - Remove this
const PAGEDESIGNER_TO_COMPONENT = {
    'commerce_assets.photoTile': ImageTile,
    'commerce_layouts.carousel': Carousel,
    // ...
}

<Page page={page} components={PAGEDESIGNER_TO_COMPONENT} />
```

**Create** a registry file at `app/page-designer/registry.js`:

```jsx
import {registry} from '@salesforce/commerce-sdk-react'

export function initializeRegistry() {
  // Commerce Assets
  registry.registerImporter('commerce_assets.imageTile', () => import('./assets/image-tile'))
  registry.registerImporter('commerce_assets.imageAndText', () =>
    import('./assets/image-with-text')
  )
  registry.registerImporter('commerce_assets.productTile', () => import('./assets/product-tile'))

  // Commerce Layouts
  registry.registerImporter('commerce_layouts.carousel', () => import('./layouts/carousel'))
  registry.registerImporter('commerce_layouts.mobileGrid1r1c', () =>
    import('./layouts/mobileGrid1r1c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid2r1c', () =>
    import('./layouts/mobileGrid2r1c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid2r2c', () =>
    import('./layouts/mobileGrid2r2c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid2r3c', () =>
    import('./layouts/mobileGrid2r3c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid3r1c', () =>
    import('./layouts/mobileGrid3r1c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid3r2c', () =>
    import('./layouts/mobileGrid3r2c')
  )
}
```

**Update** your page-viewer to use the registry:

```jsx
// app/pages/page-viewer/index.jsx
import React from 'react'
import {useParams} from 'react-router-dom'
import {Box} from '@salesforce/retail-react-app/app/components/shared/ui'
import {usePage} from '@salesforce/commerce-sdk-react'
import {Page} from '@salesforce/commerce-sdk-react/components'
import {HTTPError, HTTPNotFound} from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors'

const PageViewer = () => {
  const {pageId} = useParams()
  const {data: page, error} = usePage({parameters: {pageId}})

  if (error) {
    let ErrorClass = error.response?.status === 404 ? HTTPNotFound : HTTPError
    throw new ErrorClass(error.response?.statusText)
  }

  return (
    <Box layerStyle={'page'}>
      {/* No components prop needed - registry handles it */}
      <Page page={page} />
    </Box>
  )
}

export default PageViewer
```

#### Step 6: Set Up PageDesignerProvider in App Component

Update your main `_app/index.jsx` to initialize the registry and wrap with PageDesignerProvider:

```jsx
// app/components/_app/index.jsx
import {PageDesignerProvider} from '@salesforce/commerce-sdk-react/components'
import {useUsid} from '@salesforce/commerce-sdk-react'
import {initializeRegistry} from '@salesforce/retail-react-app/app/page-designer/registry'

// Initialize registry synchronously at module load time so components are available during SSR
initializeRegistry()

const App = (props) => {
  const {children} = props
  const {usid} = useUsid()

  // Detect Page Designer mode from URL
  const pageDesignerMode = useMemo(() => {
    const queryParams = location?.search || ''
    if (queryParams.includes('mode=EDIT')) return 'EDIT'
    if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW'
    return undefined
  }, [])

  return (
    <Box className="sf-app">
      {/* Other providers... */}
      <PageDesignerProvider
        clientId="pwa-kit-client"
        targetOrigin="*"
        usid={usid}
        mode={pageDesignerMode}
      >
        {children}
      </PageDesignerProvider>
    </Box>
  )
}
```

**Key setup points**:

1. **Initialize registry at module level** (outside the component) so components are available during SSR.
2. **Pass `usid`** from `useUsid()` hook to the provider for session tracking.
3. **Detect mode from URL** - Page Designer passes `mode=EDIT` or `mode=PREVIEW` as query parameters.
4. **Always wrap with PageDesignerProvider** - it handles both design mode and normal rendering.

#### Step 7: Create PageDesignerInit Component

Create `app/components/page-designer-init/index.jsx` to handle design mode behaviors:

```jsx
import React, {useEffect} from 'react'
import {Prompt} from 'react-router-dom'
import {usePageDesignerMode} from '@salesforce/commerce-sdk-react/components'
import {useGlobalAnchorBlock} from '@salesforce/retail-react-app/app/hooks/use-global-anchor-block'

export function PageDesignerInit() {
  const {isDesignMode} = usePageDesignerMode()

  useGlobalAnchorBlock(isDesignMode)

  useEffect(() => {
    if (isDesignMode) {
      void import('@salesforce/storefront-next-runtime/design/styles.css')
    }
  }, [isDesignMode])

  return <Prompt when={isDesignMode} message={() => false} />
}

export default PageDesignerInit
```

#### Step 8: Create useGlobalAnchorBlock Hook

Create `app/hooks/use-global-anchor-block.js` to prevent link navigation in design mode:

```jsx
import {useEffect} from 'react'

export function useGlobalAnchorBlock(enabled = true) {
  useEffect(() => {
    if (typeof window === 'undefined' || !enabled) return

    function preventAnchorClicks(event) {
      const anchor = event.target.closest('a')
      // Allow links with data-pd-allow-link attribute
      if (anchor && !anchor.hasAttribute('data-pd-allow-link')) {
        event.preventDefault()
      }
    }

    document.addEventListener('click', preventAnchorClicks)
    return () => document.removeEventListener('click', preventAnchorClicks)
  }, [enabled])
}
```

#### Step 9: Add PageDesignerInit to App

In `app/components/_app/index.jsx`, render `PageDesignerInit` inside the provider:

```jsx
import {PageDesignerInit} from '@salesforce/retail-react-app/app/components/page-designer-init'

// Inside your App component's return:
;<PageDesignerProvider
  clientId="pwa-kit-client"
  targetOrigin="*"
  usid={usid}
  mode={pageDesignerMode}
>
  <PageDesignerInit />
  {children}
</PageDesignerProvider>
```

#### Step 10: Deploy and Test

1. Deploy your updated cartridge with headless metadata to your SFCC instance.
2. Restart your PWA Kit development server:
   ```bash
   npm start
   ```
3. Verify in Business Manager:
   - Go to **Merchant Tools > Content > Components**.
   - Your components appear with no ISML requirement.
4. Test page rendering:
   - Go to your pages (homepage, PDP, PLP).
   - Components render using the registry.
5. Test in Page Designer:
   - Open the Page Designer visual editor.
   - Edit a page - your PWA Kit site shows in the preview.
   - Drag components - changes show immediately.

### Using X509 Certificates for Signing or Encryption

Some web service integrations require the use of public key infrastructure for application layer web security, in which any messages exchanged are signed or encrypted to ensure that messages aren’t tampered with.

#### Overview

:::note X509 certificates are used for application layer security. :::

1. Get a certificate from a known certificate authority or trusted provider to sign the SOAP message to the web service. You must provide a keystore for the WS-Security actions: Signature, Encryption, and Decryption.

2. Place the keystore in the webreferences2 folder in the same cartridge as the WSDL file.

   :::note
   The name of the keystore must be the same as the WSDL file and the file extension must be that of the keystore type (jks or pkcs12). For example, for the `CheckFraud.WSDL` service and a pkcs12 keystore type, the keystore must be named `CheckFraud.pkcs12`.
   :::

3. If you have additional certificates that you want to use for your SSL connection, add them to your instance using Business Manager.

4. Create a DWScript that does the following:
   - Defines a HashMap and put your client key and password, service key and password, username and password into it.
   - Defines a HashMap for the web service request that configures the actions of the interceptor actions when a call is made to the web service. Interceptor actions are defined through methods in the WSUtil class.
   - Defines a HashMap for the web service response that configures the interceptor actions for the return message.
   - Uses the `WSUtil.setWSSecurityConfig` method to configure the actions on the server
   - Calls the web service

5. Create a custom pipeline with a script node and assign it to the script you’ve created.

#### WS-Security Web Service Template

This template shows how to use the WSUtil class to configure WS-Security for a Web service call in Salesforce B2C Commerce. However, it doesn't use sample data and can't be used to run an actual web service.

```javascript
importPackage(dw.system);
importPackage(dw.util);
importPackage(dw.ws);

var WSU_NS: String =
  "http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd";

function execute(args: PipelineDictionary): Number {
  // define a map with all the secrets
  var secretsMap: Map = new HashMap();
  secretsMap.put("myclientkey", "ckpass");
  secretsMap.put("myservicekey", "ckpass");
  secretsMap.put("username", "password");

  var requestCfg: Map = new HashMap();

  // define the ws actions to be performed
  requestCfg.put(
    WSUtil.WS_ACTION,
    WSUtil.WS_USERNAME_TOKEN +
      " " +
      WSUtil.WS_TIMESTAMP +
      " " +
      WSUtil.WS_SIGNATURE +
      " " +
      WSUtil.WS_ENCRYPT,
  );

  requestCfg.put(WSUtil.WS_USER, "username");
  requestCfg.put(WSUtil.WS_PASSWORD_TYPE, WSUtil.WS_PW_DIGEST);
  requestCfg.put(WSUtil.WS_SIG_DIGEST_ALGO, "http://www.w3.org/2001/04/xmlenc#sha256");

  // define signature properties
  // the keystore file has the basename of the WSDL file and the
  // file extension based on the keystore type (for example, HelloWorld.jks).
  // The keystore file has to be placed beside the WSDL file.
  requestCfg.put(WSUtil.WS_SIG_PROP_KEYSTORE_TYPE, "jks");
  requestCfg.put(WSUtil.WS_SIG_PROP_KEYSTORE_PW, "cspass");
  requestCfg.put(WSUtil.WS_SIG_PROP_KEYSTORE_ALIAS, "myclientkey");

  requestCfg.put(WSUtil.WS_SIGNATURE_USER, "myclientkey");

  // define enrcryption properties
  requestCfg.put(WSUtil.WS_ENC_PROP_KEYSTORE_TYPE, "jks");
  requestCfg.put(WSUtil.WS_ENC_PROP_KEYSTORE_PW, "cspass");
  requestCfg.put(WSUtil.WS_ENC_PROP_KEYSTORE_ALIAS, "myservicekey");

  requestCfg.put(WSUtil.WS_ENCRYPTION_USER, "myservicekey");
  requestCfg.put(
    WSUtil.WS_SIGNATURE_PARTS,
    "{Element}{http://schemas.xmlsoap.org/soap/envelope/}Body",
  );
  requestCfg.put(
    WSUtil.WS_ENCRYPTION_PARTS,
    "{Element}{" +
      WSU_NS +
      "}Timestamp;" +
      "{Content}{http://schemas.xmlsoap.org/soap/envelope/}Body",
  );

  // set the secrets for the callback
  requestCfg.put(WSUtil.WS_SECRETS_MAP, secretsMap);

  var responseCfg: Map = new HashMap();

  // define the ws actions to be performed for the response
  responseCfg.put(
    WSUtil.WS_ACTION,
    WSUtil.WS_TIMESTAMP + " " + WSUtil.WS_SIGNATURE + " " + WSUtil.WS_ENCRYPT,
  );

  // define signature properties
  responseCfg.put(WSUtil.WS_SIG_PROP_KEYSTORE_TYPE, "jks");
  responseCfg.put(WSUtil.WS_SIG_PROP_KEYSTORE_PW, "cspass");
  responseCfg.put(WSUtil.WS_SIG_PROP_KEYSTORE_ALIAS, "myservicekey");

  responseCfg.put(WSUtil.WS_SIGNATURE_USER, "myservicekey");

  // define decryption properties
  responseCfg.put(WSUtil.WS_ENC_PROP_KEYSTORE_TYPE, "jks");
  responseCfg.put(WSUtil.WS_ENC_PROP_KEYSTORE_PW, "cspass");
  responseCfg.put(WSUtil.WS_ENC_PROP_KEYSTORE_ALIAS, "myclientkey");

  responseCfg.put(WSUtil.WS_ENCRYPTION_USER, "myclientkey");

  // set the secrets for the callback
  responseCfg.put(WSUtil.WS_SECRETS_MAP, secretsMap);

  // do the service call
  var helloWorldService: WebReference = webreferences.HelloWorld;
  var helloSvc: Stub = helloWorldService.getDefaultService();

  WSUtil.setWSSecurityConfig(helloSvc, requestCfg, responseCfg);

  var parameter = new helloWorldService.Hello2();
  parameter.setName("Send Text from client...");
  var result = helloSvc.hello2(parameter);
  var responseMessage = result.getHello2Return();

  return PIPELET_NEXT;
}
```

### Suspense Boundary Granularity

Multiple independent [`<Suspense>`] boundaries can coexist within a single route, each encapsulating one async operation. Conceptually, each `<Suspense>` boundary acts like a `try/catch` for async. Everything inside the boundary is treated as a single loading unit, and content outside the boundary isn't affected by the suspensions within it.

This is why each promise **must** be wrapped in its own [`<Suspense>`] boundary when a component consumes multiple asynchronous data sources. If multiple promises share a single boundary, the faster promise resolves first and triggers a re-render. The still-pending slower promise then suspends the boundary again.

With separate boundaries, each promise resolves independently. Slower content continues loading with its own skeleton.

#### Correct: each Await has its own Suspense boundary

```jsx
<>
  <Suspense fallback={<SkeletonA />}>
    <Await resolve={promiseA}>{(resolved) => <ComponentA data={resolved} />}</Await>
  </Suspense>

  <Suspense fallback={<SkeletonB />}>
    <Await resolve={promiseB}>{(resolved) => <ComponentB data={resolved} />}</Await>
  </Suspense>
</>
```

#### Correct: use() wrapper components, each behind its own Suspense

```jsx
function ProductWrapper({ promise }: { promise: Promise<Product> }) {
  const product = use(promise);
  return <ProductContent product={product} />;
}

function ReviewsWrapper({ promise }: { promise: Promise<Reviews> }) {
  const reviews = use(promise);
  return <ReviewsSection reviews={reviews} />;
}

<div>
  <Suspense fallback={<ProductSkeleton />}>
    <ProductWrapper promise={productPromise} />
  </Suspense>
  <Suspense fallback={<ReviewsSkeleton />}>
    <ReviewsWrapper promise={reviewsPromise} />
  </Suspense>
</div>;
```

#### Anti-pattern: multiple promises sharing one boundary

```jsx
// ❌ BAD: Both Await children share a single Suspense boundary.
// When promise1 resolves first, Component1 renders briefly, then
// promise2 (still pending) suspends the boundary again — tearing
// down Component1 and showing <ComponentsSkeleton /> a second time.
<Suspense fallback={<ComponentsSkeleton />}>
  <div>
    <Await resolve={promise1}>{(resolved) => <Component1 resolved={resolved} />}</Await>
    <Await resolve={promise2}>{(resolved) => <Component2 resolved={resolved} />}</Await>
  </div>
</Suspense>
```

#### Anti-pattern: multiple use() calls in one component

```jsx
// ❌ BAD: Both use() calls suspend within the same component,
// which means they share the nearest parent Suspense boundary.
// Resolution of one promise triggers a re-render that re-suspends
// for the other, causing the same fallback thrashing.
function CombinedView({
  promise1,
  promise2,
}: {
  promise1: Promise<Component1Data>,
  promise2: Promise<Component2Data>,
}) {
  const data1 = use(promise1);
  const data2 = use(promise2);
  return (
    <>
      <Component1 resolved={data1} />
      <Component2 resolved={data2} />
    </>
  );
}

<Suspense fallback={<ComponentsSkeleton />}>
  <CombinedView promise1={promise1} promise2={promise2} />
</Suspense>;
```

#### Anti-pattern: nested Await inside one boundary

```jsx
// ❌ BAD: promise2 cannot even begin to resolve until promise1 is done,
// creating an artificial waterfall on top of the shared-boundary problem.
<Suspense fallback={<ComponentsSkeleton />}>
  <Await resolve={promise1}>
    {(resolved1) => (
      <>
        <Component1 resolved={resolved1} />
        <Await resolve={promise2}>{(resolved2) => <Component2 resolved={resolved2} />}</Await>
      </>
    )}
  </Await>
</Suspense>
```

:::tip **Exception:** Truly dependent promises (for example, fetching details after a list) can share a boundary because they represent one logical loading unit. :::

### useNavigate

Import `useNavigate` from `@/hooks/use-navigate` instead of from React Router. The returned navigate function applies the site and locale prefix automatically.

```typescript
import { useNavigate } from "@/hooks/use-navigate";

function MyComponent() {
  const navigate = useNavigate();

  // Navigate to a prefixed path string
  navigate("/product/123");

  // Navigate to root (resolves to the site/locale homepage, e.g., /global/en-GB/)
  navigate("/");

  // Navigate with an object
  navigate({ pathname: "/product/123", search: "?color=red" });

  // History navigation (back/forward) passes through unchanged
  navigate(-1);
}
```

### 2. Create Component Registry

Create `app/page-designer/registry.js` to register your components with lazy loading:

```jsx
import {registry} from '@salesforce/commerce-sdk-react'

export function initializeRegistry() {
  // Register layout components
  registry.registerImporter('commerce_layouts.carousel', () => import('./layouts/carousel'))
  registry.registerImporter('commerce_layouts.mobileGrid2r1c', () =>
    import('./layouts/mobileGrid2r1c')
  )

  // Register asset components
  registry.registerImporter('commerce_assets.photoTile', () => import('./assets/image-tile'))
  registry.registerImporter('commerce_assets.imageAndText', () =>
    import('./assets/image-with-text')
  )

  // Add all your Page Designer components here
}
```

### Page Designer Script Files

Each page type or component type requires a corresponding script file. The script file must have the same name as the meta definition file but with a `.js` extension. For example, `promopage.json` requires a script file named `promopage.js`.

The script file name can include only alphanumeric or underscore characters. Put the script file at the same location as its meta definition file.

`mycartridge/cartridge/experience/components/assets/headlinebanner.json`

`mycartridge/cartridge/experience/components/assets/headlinebanner.js`

The script file must include a `render` function that returns the markup for the page.

In this promotion page script file, named `promopage.js`, the context object that is passed to the `render` function is of type `dw.experience.PageScriptContext`. It provides access to:

- `context.page`—Currently rendered page
- `context.renderParameters`—Parameters passed to PageMgr.renderPage(pageID, parameters)
- `context.content`—Attributes set in the custom logic (not defined by the merchant)

```sfdocs-code {"lang":"javascript", "title":"promopage.js" }
'use strict';
var Template = require('dw/util/Template');
var HashMap = require('dw/util/HashMap');

/**
 * Render logic for the page.
 */
module.exports.render = function (context) {
    var model = new HashMap();
    // add paramters to model as required for rendering based on the given context (dw.experience.PageScriptContext):
    //   * context.page (dw.experience.Page)
    //   * context.renderParameters (String)
    //   * context.content (dw.util.Map)

    return new Template('experience/pages/promopage').render(model).text;
};
```

In this banner script file, named `banner.js`, the context object that is passed to the render function is of type `dw.experience.ComponentScriptContext`. It provides access to:

- `context.component`—The currently rendered component.
- `context.componentRenderSettings`—Render settings provided by the hosting region. Optionally override these render settings that are passed in from the region with settings specific to the component.
- `context.content`—Attributes as defined in the meta definition file for the component and then configured by the merchant in the Page Designer visual editor, or as defined in the custom logic.

```sfdocs-code {"lang":"javascript", "title":"banner.js" }
'use strict';
var Template = require('dw/util/Template');
var HashMap = require('dw/util/HashMap');

/**
 * Render logic for the component.
 */
module.exports.render = function (context) {
    var model = new HashMap();
    // add paramters to model as required for rendering based on the given context (dw.experience.ComponentScriptContext):
    //   * context.component (dw.experience.Component)
    //   * context.content (dw.util.Map)

    return new Template('experience/assets/banner').render(model).text;
};
```

### Vertical Alignment

Depending on the nature of your content, get some vertical alignment into place. I prefer my column headings to align to the bottom, while my table data aligns to the top.

td {
  vertical-align: text-top;
}
th {
  vertical-align: bottom;
}

See [Designing Tables to be Read, Not Looked At] for more justification for this approach.

# Configure Multisite URLs

Storefront Next supports serving multiple B2C Commerce sites and locales from a single deployment. Configure how site and locale identifiers appear in your URLs—in the path, as query parameters, or a combination of both.

## How Multisite URLs Work

Multisite configuration controls how site and locale identifiers appear in your storefront URLs. The `url` config determines the URL pattern, and the detection config determines how the middleware reads site and locale back from incoming requests.

Configuration is in `config.server.ts` under three areas:

- `commerce.sites` defines the available sites and their supported locales.
- `defaultSiteId` determines the fallback site when no site can be resolved from the URL, cookie, or header.
- `url` defines the URL pattern, which includes the path prefix, query parameters, and excluded routes.

### Default Template Behavior

The Storefront Next template defaults to a convention where all URLs—including the homepage—use site and locale prefixes (for example, `/global/en-GB/` for the homepage, `/global/en-GB/product/123` for subpages). Requests to bare `/` are redirected server-side to the default site and locale prefix.

|                     | Homepage (`/global/en-GB/`)   | Subpages                                    |
| ------------------- | ----------------------------- | ------------------------------------------- |
| **URL**             | Prefixed with site/locale     | Includes site/locale prefix or query params |
| **Site resolution** | From URL path or query params | From URL path or query params               |
| **Shareable?**      | Yes (deterministic from URL)  | Yes (deterministic from URL)                |

The bare `/` redirect is handled in the homepage loader (`_app._index.tsx`), so you can customize the redirect behavior as needed.

## Define Your Sites

Sites and locales are defined under `commerce.sites` in `config.server.ts`.

```typescript
// config.server.ts
export default defineConfig({
  app: {
    defaultSiteId: "RefArchGlobal",
    commerce: {
      sites: [
        {
          id: "RefArchGlobal",
          defaultLocale: "en-GB",
          defaultCurrency: "GBP",
          supportedLocales: [
            { id: "en-GB", preferredCurrency: "GBP" },
            { id: "fr-FR", preferredCurrency: "EUR" },
            { id: "it-IT", preferredCurrency: "EUR" },
            { id: "ja-JP", preferredCurrency: "JPY" },
            { id: "zh-CN", preferredCurrency: "CNY" },
          ],
          supportedCurrencies: ["EUR", "GBP"],
        },
        {
          id: "RefArch",
          defaultLocale: "en-US",
          defaultCurrency: "USD",
          supportedLocales: [{ id: "en-US", preferredCurrency: "USD" }],
          supportedCurrencies: ["USD"],
        },
      ],
    },
  },
});
```

Each field serves a specific purpose:

- **`id`** — The B2C Commerce site ID. This must match the site ID configured in Business Manager.
- **`defaultLocale`** — The locale used when no locale can be resolved from the URL, cookie, or header.
- **`defaultCurrency`** — The fallback currency when no currency preference exists.
- **`supportedLocales`** — An array of locales available for this site. Each entry includes an `id` and a `preferredCurrency` that is applied when the user selects that locale.
- **`supportedCurrencies`** — The currencies available for manual selection on this site.
- **`defaultSiteId`** — Defined at the `app` level, this determines which site is used on a first visit when no `site_id` cookie exists.

:::note Keep the `i18n.supportedLngs` array in sync with the locale `id` values across all entries in `commerce.sites[].supportedLocales`.

### MRT Data Store Sites

On by default. When `commerce.sitesFromDal` is on, live site data synced through the [MRT Data Store] replaces the static `commerce.sites` for site, locale, and currency resolution, resolved per request. `defaultSiteId`, `siteAliasMap`, and `localeAliasMap` stay static and derived from config, never from the MRT Data Store.

**Fallback behavior.** When the middleware can't get site data from the MRT Data Store, the storefront keeps serving the static `commerce.sites` and doesn't fail the request. That last case logs a warning naming the missing default and the site IDs actually present, so the issue is visible in monitoring.

**URL aliasing stays config-owned.** The MRT Data Store supplies which sites exist and their locale and currency data, but not how their URLs are aliased. `siteContextMiddleware` runs after the data store rewrite and derives each resolved site's routing `alias` from the config `siteAliasMap`, keyed by site `id` (the same key for the data store and static sites), so `siteAliasMap` and `localeAliasMap` stay the config-owned source for the `:siteId` and `:localeId` URL refs. A per-site `alias` on the data store payload would be overwritten before routing reads it, so the rewrite drops it at the source.

```bash
# Opt out via env (see README-CONFIG.md) to keep static commerce.sites authoritative
# PUBLIC__app__commerce__sitesFromDal=false
```

## Configure URL Patterns

The `url` config in `config.server.ts` controls how multisite URLs are constructed.

```typescript
url: {
    prefix: '/:siteId/:localeId',
    search: '?lng=:localeId',
    excludeRoutes: ['/resource/**', '/action/**'],
}
```

- **`prefix`** — Path segments prepended to subpage URLs. Use `:siteId` and `:localeId` as placeholders that are replaced with the resolved values at URL build time.
- **`search`** — Query parameters appended to subpage URLs. Use the same `:siteId` and `:localeId` placeholder syntax.
- **`excludeRoutes`** — Glob patterns for routes that skip prefixing (e.g., API resource routes and server actions).

Both `prefix` and `search` are optional.

When `url.search` is configured, `buildUrl` injects the search params using `searchParams.set()`. This **overwrites** any existing query param with the same key, but **preserves** all other query params.

:::warning `url.prefix` and `url.excludeRoutes` are protected configuration paths. They cannot be overridden via `PUBLIC__` environment variables at runtime.

## Use Alias Maps for Clean URLs

Map B2C Commerce site IDs and locale IDs to shorter, URL-friendly aliases.

```typescript
// config.server.ts
export default defineConfig({
  app: {
    siteAliasMap: {
      RefArchGlobal: "global",
      RefArch: "us",
    },
    localeAliasMap: {
      "en-US": "us",
      "en-GB": "gb",
    },
  },
});
```

With `siteAliasMap`, the site `RefArchGlobal` appears as `global` in URLs: `/global/en-GB/product/123`

With `localeAliasMap`, the locale `en-GB` appears as `gb`: `/global/gb/product/123`

Both alias maps are optional.

## Configure Site and Locale Detection

The URL config (`prefix`, `search`) controls how URLs are **built**. The detection config controls how site and locale are **read back** from incoming requests.

The default detection config is:

```typescript
// Default site detection
siteDetectionConfig: {
    order: ['path', 'querystring', 'cookie', 'header'],
    lookupFromPathIndex: 0,
    lookupQuerystring: 'site',
    lookupCookie: 'site_id',
    lookupHeader: 'X-Site-Id',
    caches: ['cookie'],
}

// Default locale detection
localeDetectionConfig: {
    order: ['path', 'querystring', 'cookie', 'header'],
    lookupFromPathIndex: 1,
    lookupQuerystring: 'lng',
    lookupCookie: 'lng',
    lookupHeader: 'Accept-Language',
    caches: ['cookie'],
}
```

The middleware checks each source in the specified `order` and uses the first match.

Each field controls a specific detection behavior:

- **`order`**—The priority sequence for resolving the value. The middleware tries each source in order and uses the first match. For example, `['path', 'querystring', 'cookie', 'header']` checks the URL path first, then query parameters, then cookies, then HTTP headers.
- **`lookupFromPathIndex`**—Which URL path segment to read when `'path'` is in the `order`. `0` means the first segment (e.g., `/global/en-GB/...` → `'global'`), `1` means the second segment (e.g., `/global/en-GB/...` → `'en-GB'`).
- **`lookupQuerystring`**—The query parameter name to check when `'querystring'` is in the `order`. For example, `'site'` looks for `?site=global`, and `'lng'` looks for `?lng=en-GB`.
- **`lookupCookie`**—The cookie name to check when `'cookie'` is in the `order`. For example, `'site_id'` checks the `site_id` cookie, and `'lng'` checks the `lng` cookie.
- **`lookupHeader`**—The HTTP header to check when `'header'` is in the `order`. For example, `'X-Site-Id'` checks the `X-Site-Id` request header, and `'Accept-Language'` checks the `Accept-Language` header.
- **`caches`**—Where to persist the resolved value. `['cookie']` means the resolved value is stored in a cookie for subsequent requests, ensuring consistency across page navigations.

:::important The query param key for locale must be `lng` to match the i18next cookie key and default detection config.

## Configure Site-Context Cookies

The `siteContext` config in `config.server.ts` controls how site-context cookies are stored.

```typescript
// config.server.ts
export default defineConfig({
  app: {
    siteContext: {
      currencyCookieName: "currency",
      cookieOptions: {
        httpOnly: true,
        secure: true,
        sameSite: "lax",
        maxAge: 604800, // 7 days
      },
    },
  },
});
```

- **`currencyCookieName`**—The cookie name used to persist the shopper's selected currency. Defaults to `'currency'`.
- **`cookieOptions`**—Cookie attributes that are applied to all three site-context cookies: site, locale, and currency. Valid options include `httpOnly`, `maxAge`, `secure`, `sameSite`, `path`, `domain`, and so on. These options follow the standard [Cookie] options from React Router. Defaults to `{ path: '/', sameSite: 'lax', secure: true, httpOnly: true }`.

## URL Pattern Use Cases

Below are common URL patterns you can achieve by combining `prefix`, `search`, and the corresponding detection config overrides.

### Site and Locale in the Path (Default)

```typescript
// config.server.ts
export default defineConfig({
  app: {
    url: {
      prefix: "/:siteId/:localeId",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override needed — the defaults match this URL pattern.
  },
});
```

This is the default configuration. The default detection config expects site at path index 0 and locale at path index 1, which matches this pattern.

Best for: Most multisite storefronts.

| Page                            | URL                             |
| ------------------------------- | ------------------------------- |
| Homepage (RefArchGlobal, en-GB) | `/global/en-GB/`                |
| Product (RefArchGlobal, en-GB)  | `/global/en-GB/product/123`     |
| Product (RefArch, en-US)        | `/us/en-US/product/123`         |
| Category (RefArchGlobal, it-IT) | `/global/it-IT/category/womens` |

### Locale Only in the Path

```typescript
// config.server.ts
export default defineConfig({
  app: {
    url: {
      prefix: "/:localeId",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // Required: locale moved from path index 1 to 0.
    localeDetectionConfig: { lookupFromPathIndex: 0 },
    // Recommended: explicitly remove 'path' from site detection order so the
    // middleware doesn't attempt to read a locale string (e.g., 'en-GB') as a
    // site ID. Without this override, site detection will try path index 0,
    // fail to match a valid site, and fall through — which works but is less
    // explicit. Removing 'path' from site detection is the safer and more
    // defensive approach.
    siteDetectionConfig: { order: ["querystring", "cookie", "header"] },
  },
});
```

With this pattern, the site is resolved via the detection fallback chain.

Best for: Single-site storefronts with multiple locales, or when the site is determined by cookie or domain.

| Page             | URL                      |
| ---------------- | ------------------------ |
| Homepage (en-GB) | `/en-GB/`                |
| Product (en-GB)  | `/en-GB/product/123`     |
| Product (en-US)  | `/en-US/product/123`     |
| Category (it-IT) | `/it-IT/category/womens` |

### Site in the Path, Locale in Query Params

```typescript
// config.server.ts
export default defineConfig({
  app: {
    url: {
      prefix: "/:siteId",
      search: "?lng=:localeId",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override required.
    // Site is still at path index 0 (default).
    // Locale detection tries path index 1 first (e.g., 'product'), doesn't find a valid
    // locale, and falls through to querystring where it finds ?lng=en-GB.
  },
});
```

No detection config override is required. The site is still resolved from path index 0. For locale, the default detection tries path index 1 first, doesn't find a valid locale ID there, and falls through to the `?lng=` query parameter.

Best for: Shorter path segments while keeping locale in the URL for shareability.

| Page                            | URL                                 |
| ------------------------------- | ----------------------------------- |
| Homepage (RefArchGlobal, en-GB) | `/global/?lng=en-GB`                |
| Product (RefArchGlobal, en-GB)  | `/global/product/123?lng=en-GB`     |
| Product (RefArch, en-US)        | `/us/product/123?lng=en-US`         |
| Category (RefArchGlobal, it-IT) | `/global/category/womens?lng=it-IT` |

### Everything in Query Params

```typescript
// config.server.ts
export default defineConfig({
  app: {
    url: {
      search: "?site=:siteId&lng=:localeId",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override required.
    // Path detection reads page path segments (e.g., 'product', '123'), doesn't find
    // valid site/locale IDs, and falls through to querystring where it finds
    // ?site=global&lng=en-GB.
  },
});
```

Without a `prefix`, React Router doesn't need site/locale route params in its route definitions. No detection config override is required—the default detection tries path segments first, doesn't find valid site or locale IDs, and naturally falls through to the query parameters.

Best for: Storefronts that want clean paths and don't mind query params.

| Page     | URL                                  |
| -------- | ------------------------------------ |
| Homepage | `/?site=global&lng=en-GB`            |
| Product  | `/product/123?site=global&lng=en-GB` |
| Category | `/category/womens?site=us&lng=en-US` |

### Locale Only in Query Params

```typescript
// config.server.ts
export default defineConfig({
  app: {
    url: {
      search: "?lng=:localeId",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override required.
    // Path detection doesn't find valid site/locale IDs in page path segments
    // and falls through. Site resolves from cookie or header; locale from ?lng=.
  },
});
```

No detection config override is required.

Best for: Single-site storefronts that want locale-aware URLs without path changes.

| Page     | URL                          |
| -------- | ---------------------------- |
| Homepage | `/?lng=en-GB`                |
| Product  | `/product/123?lng=en-GB`     |
| Category | `/category/womens?lng=it-IT` |

### No Prefix (Single Site)

```typescript
// config.server.ts
export default defineConfig({
  app: {
    defaultSiteId: "RefArch",
    commerce: {
      sites: [
        {
          id: "RefArch",
          defaultLocale: "en-US",
          defaultCurrency: "USD",
          supportedLocales: [{ id: "en-US", preferredCurrency: "USD" }],
          supportedCurrencies: ["USD"],
        },
      ],
    },
    url: {
      prefix: "/",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override required.
    // Path detection doesn't find valid site/locale IDs in page path segments
    // and falls through. Both site and locale resolve from cookie or header.
  },
});
```

This configuration produces the cleanest possible URLs with no site or locale identifiers at all. The multisite middleware still runs, but it resolves site and locale entirely from cookies and headers using the detection fallback chain.

No detection config override is required. The default detection tries path segments first, doesn't find valid site or locale IDs, and falls through to cookies and headers.

Best for: Single-site, single-locale storefronts that don't need site or locale identifiers in the URL.

| Page     | URL                |
| -------- | ------------------ |
| Homepage | `/`                |
| Product  | `/product/123`     |
| Category | `/category/womens` |

## Switch Sites, Locales, and Currencies

The Storefront Next template includes built-in switcher components for site, locale, and currency.

### Site Switcher

The site switcher component is at `src/components/site-switcher`.

1. The dropdown calls `i18n.changeLanguage` with the default locale of the new site.
2. A `POST` is submitted to `/action/set-site-context` with the new `siteId` and `localeId`.
3. The server action sets the `site_id` and `lng` cookies and issues a redirect.
4. The page reloads with the new site and locale applied.

### Locale Switcher

The locale switcher component is at `src/components/locale-switcher`.

1. The current URL path is stripped of its site/locale prefix using `stripPathPrefix`.
2. The new URL is rebuilt with the updated locale using `buildUrl`.
3. `i18n.changeLanguage` is called with the new locale string.
4. A `POST` is submitted to `/action/set-site-context` with the updated `localeId`.
5. The server action sets the `lng` cookie.
6. React Router triggers a full loader revalidation so all page data is reloaded with the new locale context.

### Currency Switcher

When a shopper selects a currency, the currency switcher posts the new currency to `/action/set-site-context`, which stores it in the currency cookie (default name: `currency`).

The active currency is resolved using the following priority order:

| Priority | Source                                            |
| -------- | ------------------------------------------------- |
| 1        | Currency cookie (shopper's explicit selection)    |
| 2        | `preferredCurrency` from the active locale config |
| 3        | `defaultCurrency` from the active site config     |

## Access Site Context in React Components

Use `useSite()` to access the current site, language, and currency in React components:

```typescript
import { useSite } from "@salesforce/storefront-next-runtime/site-context";

function MyComponent() {
  const { site, language, currency } = useSite();
  // site: Site object (id, supportedLocales, supportedCurrencies, etc.)
  // language: current locale ID (e.g., 'en-GB')
  // currency: current currency code (e.g., 'GBP')
}
```

`useSite()` throws if called outside a `SiteProvider`.

:::note `useSite` also returns the `locale` object that contains the i18next language string, but Storefront Next doesn't use it for locale switching.

## Navigate with Site Context

Storefront Next provides multisite-aware navigation utilities that automatically prepend the active site and locale prefix to every URL.

### Link and NavLink

Import `Link` and `NavLink` from `@/components/link` instead of from React Router.

```typescript
import { Link, NavLink } from "@/components/link";

// Renders as /global/en-GB/product/123
<Link to="/product/123">View Product</Link>

// External URLs and non-string `to` values (e.g., objects with pathname) pass
// through unchanged, so you can use the same component for all link types.
<Link to="https://example.com">External</Link>
```

### useNavigate

Import `useNavigate` from `@/hooks/use-navigate` instead of from React Router.

```typescript
import { useNavigate } from "@/hooks/use-navigate";

function MyComponent() {
  const navigate = useNavigate();

  // Navigate to a prefixed path string
  navigate("/product/123");

  // Navigate to root (resolves to the site/locale homepage, e.g., /global/en-GB/)
  navigate("/");

  // Navigate with an object
  navigate({ pathname: "/product/123", search: "?color=red" });

  // History navigation (back/forward) passes through unchanged
  navigate(-1);
}
```

### useCurrentSiteAndLocaleRef

Use the `useCurrentSiteAndLocaleRef` hook when you need to build URLs manually outside of Link or useNavigate:

```typescript
import { useCurrentSiteAndLocaleRef } from "@salesforce/storefront-next-runtime/site-context";
import { buildUrl } from "@/lib/url";
import { useConfig } from "@salesforce/storefront-next-runtime/config";

function MyComponent() {
  const config = useConfig();
  const currentSiteAndLocaleRef = useCurrentSiteAndLocaleRef();

  const url = buildUrl("/product/123", config.app.url, currentSiteAndLocaleRef.current);
  // url: /global/en-GB/product/123
}
```

### React Router Form Actions

React Router's `<Form>` component does **not** go through `buildUrl`.

```typescript
import { Form } from "react-router";
import { buildUrl } from "@/lib/url";
import { useConfig } from "@salesforce/storefront-next-runtime/config";
import { useCurrentSiteAndLocaleRef } from "@salesforce/storefront-next-runtime/site-context";

function SearchForm() {
  const config = useConfig();
  const currentSiteAndLocaleRef = useCurrentSiteAndLocaleRef();

  const action = buildUrl("/action/search", config.app.url, currentSiteAndLocaleRef.current);

  return (
    <Form method="post" action={action}>
      ...
    </Form>
  );
}
```

:::warning Using `<Form action="/some-path">` without prefixing produces a URL without the site/locale prefix, which causes a 404 error. :::

## Important Considerations

1. **Homepage URL uses site and locale prefix.** All URLs—including the homepage—use the configured site and locale prefix (e.g., `/global/en-GB/`). Requests to bare `/` are redirected server-side to the default site and locale prefix. This redirect is handled in the homepage loader (`_app._index.tsx`) and can be customized.

2. **URL prefix changes require a rebuild.** `url.prefix` and `url.excludeRoutes` are protected paths. They can't be changed via `PUBLIC__` environment variables. Update `config.server.ts` and rebuild the application.

3. **Detection config overrides are only required when path indexes shift.** The detection middleware uses a fallback chain—if it doesn't find a valid site or locale at the current source, it moves to the next one. In most non-default URL patterns, path detection simply fails to match and falls through to querystring or cookie. The only case where an override is **required** is when a path segment's position changes (e.g., locale moves from index 1 to index 0 in a locale-only prefix).

4. **Query param keys are not arbitrary.** The locale query param key must be `lng` (matching the i18next cookie). The site key defaults to `site`. Custom keys require matching updates to the detection config.

5. **Use multisite-aware navigation.** Always use `Link` and `NavLink` from `@/components/link`, `useNavigate` from `@/hooks/use-navigate`, and `buildUrlFromContext` for server-side redirects. These automatically apply the URL prefix. Using React Router's `Link` or `redirect` directly produces URLs without the prefix, resulting in 404 errors.

   In loaders and actions, use `buildUrlFromContext` from `@/lib/url.server` to build redirect URLs:

   ```typescript
   import { redirect } from "react-router";
   import { buildUrlFromContext } from "@/lib/url.server";

   export async function loader({ request, context }: LoaderFunctionArgs) {
     if (!isAuthenticated) {
       // bare redirect('/login') produces a URL without the prefix → 404
       throw redirect(buildUrlFromContext("/login", context));
     }
   }
   ```

6. **Keep i18n and site config in sync.** The locale IDs in your `i18n.supportedLngs` must match the `id` values in `commerce.sites[].supportedLocales`. A mismatch causes the locale switcher to show unsupported locales or hide valid ones.

7. **Always include framework routes in excludeRoutes.** The `/resource/**` and `/action/**` patterns must remain in `excludeRoutes`. Removing them causes resource routes and server actions to be incorrectly prefixed with site/locale segments.

8. **Prefix React Router Form action values manually.** React Router's `<Form>` component does not go through `buildUrl`. If you use `<Form action="/some-path">`, prefix the action yourself using `buildUrl` with `useConfig` and `useCurrentSiteAndLocaleRef`. See [Navigate with Site Context] for a code example.

